globalThis.KENGURU_CHOICE_LAYOUTS = {"2001-3-4/2":{"options":[{"image":"assets/separated-choices/2001-3-4/02-1.webp","pixelWidth":78,"pixelHeight":78},{"image":"assets/separated-choices/2001-3-4/02-2.webp","pixelWidth":78,"pixelHeight":76},{"image":"assets/separated-choices/2001-3-4/02-3.webp","pixelWidth":78,"pixelHeight":77},{"image":"assets/separated-choices/2001-3-4/02-4.webp","pixelWidth":77,"pixelHeight":78},{"image":"assets/separated-choices/2001-3-4/02-5.webp","pixelWidth":78,"pixelHeight":78}],"condition":{"src":"assets/separated-choices/2001-3-4/02-condition.webp","width":348,"height":73}},"2001-3-4/7":{"options":[{"text":"20 м/с"},{"text":"1 км/мин"},{"text":"4000 м/ч"},{"text":"900 м/мин"},{"text":"45 км/ч"}]},"2001-3-4/13":{"options":[{"text":"252"},{"text":"248"},{"text":"250"},{"text":"249"},{"text":"Среди ответов A–D нет верного"}]},"2001-3-4/14":{"options":[{"image":"assets/separated-choices/2001-3-4/14-1.webp","pixelWidth":65,"pixelHeight":107},{"image":"assets/separated-choices/2001-3-4/14-2.webp","pixelWidth":103,"pixelHeight":83},{"image":"assets/separated-choices/2001-3-4/14-3.webp","pixelWidth":119,"pixelHeight":65},{"image":"assets/separated-choices/2001-3-4/14-4.webp","pixelWidth":77,"pixelHeight":109},{"image":"assets/separated-choices/2001-3-4/14-5.webp","pixelWidth":101,"pixelHeight":83}]}};
globalThis.KENGURU_LEGACY = [[2001,"3–4 классы",[[816,96,"Кенгуру складывает двести сотен и один. Подскажите правильный ответ.",{"0":[33.8,64.9,31.4,26.3],"1":[181,64.9,31.4,26.3],"2":[350.2,64.9,32.6,26.3],"3":[500.2,64.9,32.7,26.3],"4":[650.3,64.9,31.7,26.3]},"D","Двести сотен",[["Считаем сотни","В одной сотне 100. Значит, двести сотен — это 200 × 100 = 20 000."],["Прибавляем один","20 000 + 1 = 20 001."]],""],[816,213,"",{},"B","Зеркальная пятёрка",[["Ищем правило","Каждый рисунок состоит из цифры и её отражения в вертикальном зеркале. Например, у двойки две наклонные черты сходятся внизу."],["Соединяем половины","У пятёрки совмещаем вертикальные штрихи. Верхние черты расходятся влево и вправо, а круглые части вместе образуют овал. Так устроен рисунок B."]],""],[816,97,"У Йозефа было 7 палочек. Он разломал одну из них пополам. Сколько теперь у него палочек?",{"0":[33.8,64.9,31.5,26.3],"1":[181,64.9,31.5,26.3],"2":[350.3,64.9,32.6,26.3],"3":[519.5,64.9,32.6,26.3],"4":[688.7,64.9,31.3,26.3]},"D","Сломанная палочка",[["Считаем целые","Шесть из семи палочек остались целыми."],["Считаем обломки","Сломанная палочка дала две новые. Всего стало 6 + 2 = 8 палочек."]],""],[816,116,"Катя написала фразу «Я люблю решать задачи», подсчитала количество букв в каждом слове и перемножила полученные числа. Какой результат должен был получиться?",{"0":[33.9,82.9,31.5,26.3],"1":[181.1,82.9,31.5,26.3],"2":[350.4,82.9,32.6,26.3],"3":[519.5,82.9,32.6,26.3],"4":[688.7,82.9,31.4,26.3]},"E","Буквы в словах",[["Считаем буквы","В слове «я» 1 буква, в слове «люблю» — 5, в слове «решать» — 6 и в слове «задачи» — 6."],["Перемножаем","1 × 5 × 6 × 6 = 5 × 36 = 180."]],""],[816,137,"родился, когда Ане исполнилось 3 года. Сколько лет будет Пете, когда Аня будет вдвое его старше?",{"0":[33.8,80.8,31.4,26.3],"1":[181,80.8,31.4,26.3],"2":[350.2,80.8,32.7,26.3],"3":[33.8,106.5,32.7,26.3],"4":[181,106.5,31.4,26.3]},"C","Два дня рождения",[["Замечаем разницу","У Пети и Ани день рождения в один день. Аня всегда на 3 года старше Пети."],["Сравниваем возрасты","Чтобы Аня была вдвое старше, разница в 3 года должна равняться возрасту Пети. Ему будет 3 года, а Ане — 6 лет."]],""],[816,173,"",{},"B","Фигуры на мордочке",[["Рассматриваем детали","Мордочка и глаза круглые, нос квадратный, а зубы образуют прямоугольник."],["Проверяем ушки","У каждого уха два прямых края и дуга со стороны головы. Треугольнику нужны три прямых стороны. Таких фигур на рисунке нет."]],""],[816,93,"С какой скоростью школьник Вова может идти из школы домой? м км м м км",{"0":[33.7,49.8,31.4,26.3],"1":[181,49.8,31.4,26.3],"2":[329.2,49.8,32.7,26.3],"3":[488.1,49.8,32.7,26.3],"4":[650.8,49.8,31.4,26.3]},"C","Скорость ходьбы",[["Переводим в километры в час","20 м/с — это 72 км/ч; 1 км/мин — 60 км/ч; 900 м/мин — 54 км/ч. В последнем варианте уже записано 45 км/ч."],["Выбираем скорость пешехода","4 000 м/ч — это 4 км/ч. Такая скорость подходит для обычной ходьбы."]],""],[816,109,"Во дворе школы играют 19 девочек и 12 мальчиков. Какое количество ребят должно к ним присоединиться, чтобы все они могли разбиться на 6 равных команд?",{},"E","Шесть команд",[["Считаем ребят","Во дворе 19 + 12 = 31 ребёнок."],["Собираем равные команды","Для шести команд по пять человек хватило бы 30 детей. Следующее подходящее число — 36, по шесть человек в команде. Нужно ещё 36 − 31 = 5 детей."]],""],[817,187,"Джимми купил в подарок своей маме шоколадное сердечко. Сколько весит эта шоколадка, если каждый квадратик весит 10 г?",{"0":[33.8,89.3,31.4,26.3],"1":[181,89.3,31.4,26.3],"2":[350.2,89.3,32.7,26.3],"3":[33.8,116.2,32.7,26.3],"4":[181,116.2,31.4,26.3]},"D","Шоколадное сердце",[["Считаем клетки по рядам","Соединяем половинки клеток попарно. В двух верхних рядах получаем 2 и 6 целых клеток. В двух средних рядах — по 8."],["Досчитываем массу","Нижние ряды дают 7 + 5 + 3 + 1 = 16 клеток. Всего 2 + 6 + 8 + 8 + 16 = 40 клеток, а шоколадка весит 40 × 10 = 400 г."]],""],[817,246,"В магазин обуви пришли 4 сороконожки в одинаковых башмачках (у каждой из них по 20 пар ног). У одной из сороконожек не хватало обуви на задней половине ног, у другой – на передней половине, у третьей обуты были только правые ножки, а у четвертой − только левые. Они купили в магазине обувь и ушли полностью обутые. Сколько пар обуви купили сороконожки в магазине?",{"0":[33.9,182.9,31.5,26.3],"1":[181.1,182.9,31.5,26.3],"2":[350.3,182.9,32.6,26.3],"3":[519.5,182.9,32.6,26.3],"4":[688.7,182.9,31.4,26.3]},"C","Обувь сороконожек",[["Считаем босые ножки","У каждой сороконожки 40 ног. У каждой обута половина, поэтому все вместе они купили 4 × 20 = 80 башмачков."],["Собираем пары","На каждую пару идут два башмачка. Всего купили 80 ÷ 2 = 40 пар."]],""],[817,264,"Вика завязала бантик над правым ухом и вертится пред зеркалом. Сколько из следующих изображений можно увидеть в зеркале?",{"0":[33.9,232.4,31.5,26.3],"1":[181.2,232.4,31.5,26.3],"2":[350.4,232.4,32.6,26.3],"3":[519.6,232.4,32.6,26.3],"4":[688.8,232.4,31.3,26.3]},"D","Бант в зеркале",[["Смотрим прямо","Бантик над правым ухом Вики. Когда она смотрит прямо в зеркало, бантик у отражения виден справа от нас, как на третьем рисунке."],["Проверяем повороты","На четвёртом рисунке виден бок с бантом, на втором — бок без банта. Со спины бант в отражении должен быть слева от нас, поэтому первый рисунок отпадает. Подходят три рисунка."]],""],[817,139,"Нескольким кенгуру раздали 50 яблок так, чтобы каждый кенгуру получил хотя бы по одному яблоку и ни у каких двух кенгуру не было поровну яблок. Какое наибольшее количество кенгуру могли получить яблоки?",{"0":[33.7,107.5,31.5,26.3],"1":[181,107.5,31.5,26.3],"2":[350.2,107.5,32.6,26.3],"3":[519.4,107.5,32.6,26.3],"4":[688.6,107.5,31.4,26.3]},"B","Яблоки для кенгуру",[["Берём самые маленькие числа","Чтобы накормить как можно больше кенгуру, начнём с 1 яблока и дадим каждому следующему на 1 больше. Для 10 кенгуру потребуется как минимум 1 + 2 + … + 10 = 55 яблок."],["Проверяем девятерых","Для девяти достаточно 1 + 2 + … + 9 = 45 яблок. Оставшиеся 5 отдадим тому, кто получил 9. У всех всё ещё разное количество. Максимум — 9 кенгуру."]],""],[817,166,"Бетти и Кетти путешествуют на суперпоезде. Бетти едет в сто семнадцатом вагоне с начала поезда, а Кетти – в сто тридцать четвертом с конца. Оказалось, что они едут в соседних вагонах. Сколько вагонов могло быть в поезде?",{},"D","Соседние вагоны",[["Выбираем соседей","Бетти едет в вагоне № 117 с начала. Соседний вагон Кетти может иметь номер 116 или 118."],["Считаем от обоих концов","Вместе с вагоном Кетти от начала до неё 116 или 118 вагонов, а от неё до конца — 134. Её вагон посчитан дважды. Получаем 116 + 134 − 1 = 249 или 118 + 134 − 1 = 251. Среди вариантов есть 249."]],""],[817,175,"",{},"E","Повороты фигур",[["Находим общий ряд","В каждой фигуре есть прямой ряд из четырёх кубиков и два выступающих кубика. Один выступ примыкает к концу ряда."],["Сравниваем второй выступ","Начнём счёт с конца, где прикреплён первый выступ. В A, B, C и D второй выступ прикреплён к третьему кубику ряда. В E — ко второму, поэтому поворотом её не совместить с остальными."]],""],[816,220,"Пятеро друзей выясняли, какой сегодня день недели. Андрей сказал: «Позавчера была пятница». Володя сказал: «Послезавтра будет вторник». Сережа сказал: «Вчера была суббота». Дима сказал: «Завтра будет понедельник». Егор сказал: «Сегодня четверг». Один их них ошибся. Кто?",{"0":[33.7,186.5,31.4,26.3],"1":[180.9,186.5,31.4,26.3],"2":[350.1,186.5,32.7,26.3],"3":[519.4,186.5,32.7,26.3],"4":[669,186.5,31.4,26.3]},"E","Какой сегодня день?",[["Устанавливаем день","Если вчера была суббота, сегодня воскресенье. Тогда позавчера и правда была пятница, завтра будет понедельник, а послезавтра — вторник."],["Находим ошибку","Четверо друзей назвали дни, которые подходят воскресенью. Только Егор сказал, что сегодня четверг."]],""],[816,97,"На столе лежат пятиугольники и шестиугольники. Всего у них ровно 37 вершин. Сколько пятиугольников на столе?",{"0":[33.8,64.9,31.5,26.3],"1":[181.1,64.9,31.5,26.3],"2":[350.3,64.9,32.6,26.3],"3":[519.5,64.9,32.6,26.3],"4":[688.7,64.9,31.3,26.3]},"E","Пять или шесть вершин",[["Считаем фигуры","У шести фигур было бы не больше 6 × 6 = 36 вершин, а у восьми — не меньше 8 × 5 = 40. Значит, фигур ровно семь."],["Заменяем шестиугольники","Если бы все семь фигур были шестиугольниками, у них было бы 42 вершины. Каждая замена шестиугольника пятиугольником убирает одну вершину. Чтобы получить 37, нужно пять пятиугольников."]],""],[816,123,"Четырехзначное число начинается с цифры 5. Эту цифру переставили в конец числа. Полученное число оказалось на 747 меньше исходного. Какова сумма цифр этого числа?",{"0":[33.8,89.1,31.5,26.3],"1":[181.1,89.1,31.5,26.3],"2":[350.3,89.1,32.6,26.3],"3":[519.5,89.1,32.6,26.3],"4":[688.6,89.1,31.4,26.3]},"D","Пятёрка переезжает",[["Выделяем три цифры","Назовём число из трёх последних цифр хвостом. Исходное число — это 5 000 плюс хвост. После перестановки цифры получаем хвост, умноженный на 10, плюс 5."],["Находим хвост","Разность 747 получается, если из 4 995 вычесть девять хвостов. Поэтому девять хвостов составляют 4 995 − 747 = 4 248, а хвост равен 472."],["Складываем цифры","Цифры числа — 5, 4, 7, 2. Их сумма равна 18."]],""],[816,170,"В ряд стоят три коробки, в каждой по 11 конфет. Я беру по одной конфете из каждой коробки в таком порядке: левая, центральная, правая, центральная, левая, центральная, и так далее до тех пор, пока в центральной коробке не закончатся конфеты. В одной из двух крайних коробок осталось больше конфет. Сколько?",{"0":[33.8,137.8,31.5,26.3],"1":[181.1,137.8,31.5,26.3],"2":[350.3,137.8,32.6,26.3],"3":[519.5,137.8,32.6,26.3],"4":[688.7,137.8,31.3,26.3]},"D","Конфеты в коробках",[["Замечаем чередование","После каждой конфеты из крайней коробки берут конфету из центральной. Поэтому к тому моменту, как из центра взяли все 11 конфет, из крайних взяли тоже 11."],["Считаем по сторонам","Из крайних коробок берут по очереди, начиная с левой. Взяли 6 слева и 5 справа. Справа осталось больше — 11 − 5 = 6 конфет."]],""],[816,147,"На игральном кубике общее число точек на любых двух противоположных гранях равно 7. Дженни склеила столбик из 6 таких кубиков и подсчитала общее число точек на всех наружных гранях. Какое самое большое число она могла получить?",{"0":[33.8,113.5,31.4,26.3],"1":[181,113.5,31.4,26.3],"2":[350.3,113.5,32.6,26.3],"3":[519.4,113.5,32.6,26.3],"4":[688.6,113.5,31.4,26.3]},"B","Кубики в столбике",[["Считаем боковые точки","На каждом кубике снаружи четыре боковые грани. Две пары противоположных граней дают 7 + 7 = 14 точек. У шести кубиков сбоку 84 точки."],["Выбираем верх и низ","Верхнюю и нижнюю наружные грани можно обе повернуть шестёркой наружу. Получаем максимум 84 + 6 + 6 = 96 точек."]],""],[816,99,"Сколько существует трехзначных чисел, у которых сумма цифр равна 4?",{"0":[33.7,64.9,31.5,26.3],"1":[181,64.9,31.5,26.3],"2":[350.3,64.9,32.6,26.3],"3":[519.4,64.9,32.6,26.3],"4":[688.6,64.9,31.3,26.3]},"A","Сумма цифр четыре",[["Выбираем сотни","В разряде сотен может стоять 1, 2, 3 или 4. Тогда на десятки и единицы остаётся соответственно 3, 2, 1 или 0."],["Перебираем пары","Сумму 3 дают четыре пары: 0 и 3, 1 и 2, 2 и 1, 3 и 0. Для суммы 2 есть три пары, для суммы 1 — две, для суммы 0 — одна. Всего 4 + 3 + 2 + 1 = 10 чисел."]],""],[816,193,"Задачи, оцениваемые в 5 баллов 21. Какое самое маленькое число спичек можно добавить к этой фигуре, чтобы получить точно 11 квадратов?",{"0":[33.7,132,31.5,26.3],"1":[211.7,132,31.5,26.3],"2":[395.1,132,32.6,26.3],"3":[33.7,159.1,32.6,26.3],"4":[211.6,159.1,31.4,26.3]},"A","Квадраты из спичек",[["Считаем готовые квадраты","На рисунке три квадрата со стороной 1 спичка, два со стороной 2 спички и три со стороной 3 спички. Всего восемь."],["Проверяем одну спичку","У квадратов со стороной 2 спички и больше либо все стороны уже есть, либо не хватает хотя бы двух спичек. Среди маленьких квадратов нет двух незаконченных с одной и той же недостающей спичкой. Значит, одной спичкой можно добавить самое большее один квадрат."],["Ставим две спички","В верхнем из двух квадратов со стороной 2 спички достраиваем крестик от верхней и левой сторон до его центра. Выйдут три новых маленьких квадрата. Теперь их вместе с прежними ровно 11."]],""],[816,147,"Есть 6 карточек с цифрами 1, 2, 3, 4, 5 и 6. Используя их, можно составить два трехзначных числа, например, 645 и 321. Вася составил эти числа так, что их разность оказалась самой маленькой из всех возможных. Эта разность равна",{"0":[33.7,113.5,31.4,26.3],"1":[181,113.5,31.4,26.3],"2":[350.2,113.5,32.6,26.3],"3":[519.4,113.5,32.6,26.3],"4":[688.5,113.5,31.4,26.3]},"D","Ближайшие числа",[["Сравниваем сотни","У большего числа цифра сотен выше хотя бы на 1. Разницу сотен не меньше 100 могут сильнее всего сблизить хвосты 12 у большего и 65 у меньшего."],["Строим подходящую пару","Цифры 1, 2, 6 и 5 уже заняты, поэтому берём для сотен соседние 3 и 4. Получаем 412 − 365 = 47. Меньше нельзя, ведь хвосты уже уменьшили разность на максимально возможные 65 − 12 = 53."]],""],[816,234,"Кубик лежит на листе бумаги в клетку, как показано на рисунке. Кубик перекатывают через ребра в направлениях, указанных стрелочками. Сколько точек окажется сверху, когда кубик попадет на клетку, отмеченную звездочкой?",{"0":[33.8,203.2,31.4,26.3],"1":[180.9,203.2,31.4,26.3],"2":[350.1,203.2,32.6,26.3],"3":[467.2,203.2,32.7,26.3],"4":[584.7,203.2,31.4,26.3]},"B","Кубик по стрелкам",[["Определяем грани","Сверху 3, спереди 1, справа 2. На противоположных гранях обычного игрального кубика в сумме 7, значит слева 5, сзади 6, снизу 4."],["Следим за первыми поворотами","После переката вправо сверху 5, справа 3, а спереди по-прежнему 1. При перекате от себя передняя грань 1 оказывается сверху, а нижняя грань 2 — спереди."],["Доходим до звезды","Ещё один перекат вправо оставляет 2 спереди. Последний перекат от себя поднимает эту грань наверх. Сверху две точки."]],""],[816,249,"Какие два из нарисованных восьмиугольников раскрашены одинаково?",{"0":[33.7,216.9,31.4,26.3],"1":[181,216.9,31.4,26.3],"2":[350.1,216.9,32.6,26.3],"3":[519.4,216.9,32.6,26.3],"4":[656.5,216.9,31.4,26.3]},"D","Узор на восьмиугольнике",[["Выбираем ориентир","У восьмиугольника 4 есть большой тёмный треугольник у верхней стороны и маленький тёмный треугольник у нижнего правого угла."],["Поворачиваем рисунок","При повороте по часовой стрелке на четверть оборота большой треугольник окажется справа, маленький — у нижнего левого угла. Если сравнить и остальные закрашенные части, узор совпадёт с восьмиугольником 6."]],""],[816,122,"Про число a известно, что его последняя цифра равна 1, и что оно делится ровно на десять различных чисел (включая 1 и a). На сколько различных чисел делится число 10a?",{},"C","Делители числа",[["Проверяем последнюю цифру","Число оканчивается на 1, поэтому среди его делителей нет чисел, кратных 2 или 5. Множитель 10 добавляет ровно одну двойку и одну пятёрку."],["Собираем все варианты","Любой делитель нового числа получается из делителя старого, к которому можно приписать множитель 1, 2, 5 или 10. Все варианты различны. Всего 10 × 4 = 40 делителей."]],""],[816,196,"Три черепахи – Анди, Банди и Канди – соревнуются в беге на дистанцию 30 м. Они стартовали одновременно. Когда Анди финишировала, Банди оставалось до финиша 10 м, а Канди была на 4 м впереди Банди. На каком расстоянии до финиша будет Банди, когда Канди закончит дистанцию, если каждая черепаха движется с постоянной скоростью?",{"0":[33.8,162.2,31.4,26.3],"1":[181,162.2,31.4,26.3],"2":[350.2,162.2,32.7,26.3],"3":[519.4,162.2,32.7,26.3],"4":[688.7,162.2,31.4,26.3]},"D","Черепаший забег",[["Сравниваем пути","Когда Анди финиширует, Банди пробежала 30 − 10 = 20 м, а Канди — 20 + 4 = 24 м."],["Считаем оставшуюся часть","За равное время Банди пробегает 5 м, а Канди — 6 м, потому что 20 и 24 делятся на 4. Канди осталось как раз 6 м. Банди за это время пробежит ещё 5 м, и ей останется 10 − 5 = 5 м."]],""]]]];
globalThis.KENGURU_LEGACY_CONDITIONS = {"2001":{"1":{"question":"Кенгуру складывает двести сотен и один. Подскажите правильный ответ.","choices":["201","1201","2001","20001","200001"]},"2":{"question":"На четырех рисунках изображены цифры от 1 до 4 вместе со своими зеркальными изображениями. Каким будет следующий рисунок?","image":"assets/legacy-conditions/2001/manual-02.webp","imageWidth":673,"imageHeight":171},"3":{"question":"У Йозефа было 7 палочек. Он разломал одну из них пополам. Сколько теперь у него палочек?","choices":["5","6","7","8","9"]},"4":{"question":"Катя написала фразу «Я люблю решать задачи», подсчитала количество букв в каждом слове и перемножила полученные числа. Какой результат должен был получиться?","choices":["18","30","36","150","180"]},"5":{"question":"Петя и Аня отмечают свой день рождения 16 марта, но Петя родился, когда Ане исполнилось 3 года. Сколько лет будет Пете, когда Аня будет вдвое его старше?","choices":["1 год","2 года","3 года","4 года","10 лет"]},"6":{"question":"Каких геометрических фигур нет на рисунке?","choices":["прямоугольников","треугольников","квадратов","кругов","все эти фигуры есть"],"image":"assets/legacy-conditions/2001/task-06.webp","imageWidth":411,"imageHeight":513},"7":{"question":"С какой скоростью школьник Вова может идти из школы домой?","image":"assets/legacy-conditions/2001/task-07.webp","imageWidth":933,"imageHeight":64},"8":{"question":"Во дворе школы играют 19 девочек и 12 мальчиков. Какое количество ребят должно к ним присоединиться, чтобы все они могли разбиться на 6 равных команд?","choices":["1","2","3","4","5"]},"9":{"question":"Джимми купил в подарок своей маме шоколадное сердечко. Сколько весит эта шоколадка, если каждый квадратик весит 10 г?","choices":["340 г","360 г","380 г","400 г","420 г"],"image":"assets/legacy-conditions/2001/task-09.svg","imageWidth":220,"imageHeight":218},"10":{"question":"В магазин обуви пришли 4 сороконожки в одинаковых башмачках (у каждой из них по 20 пар ног). У одной из сороконожек не хватало обуви на задней половине ног, у другой – на передней половине, у третьей обуты были только правые ножки, а у четвертой − только левые. Они купили в магазине обувь и ушли полностью обутые. Сколько пар обуви купили сороконожки в магазине?","choices":["10","20","40","60","80"]},"11":{"question":"Вика завязала бантик над правым ухом и вертится пред зеркалом. Сколько из следующих изображений можно увидеть в зеркале?","choices":["0","1","2","3","4"],"image":"assets/legacy-conditions/2001/task-11.webp","imageWidth":915,"imageHeight":195},"12":{"question":"Нескольким кенгуру раздали 50 яблок так, чтобы каждый кенгуру получил хотя бы по одному яблоку и ни у каких двух кенгуру не было поровну яблок. Какое наибольшее количество кенгуру могли получить яблоки?","choices":["10","9","8","6","5"]},"13":{"question":"Бетти и Кетти путешествуют на суперпоезде. Бетти едет в сто семнадцатом вагоне с начала поезда, а Кетти – в сто тридцать четвертом с конца. Оказалось, что они едут в соседних вагонах. Сколько вагонов могло быть в поезде?","image":"assets/legacy-conditions/2001/task-13.webp","imageWidth":731,"imageHeight":75},"14":{"question":"На каком из следующих рисунков изображена фигура не такая, как на остальных?","image":"assets/legacy-conditions/2001/manual-14.webp","imageWidth":735,"imageHeight":119},"15":{"question":"Пятеро друзей выясняли, какой сегодня день недели. Андрей сказал: «Позавчера была пятница». Володя сказал: «Послезавтра будет вторник». Сережа сказал: «Вчера была суббота». Дима сказал: «Завтра будет понедельник». Егор сказал: «Сегодня четверг». Один их них ошибся. Кто?","choices":["Андрей","Володя","Сережа","Дима","Егор"]},"16":{"question":"На столе лежат пятиугольники и шестиугольники. Всего у них ровно 37 вершин. Сколько пятиугольников на столе?","choices":["1","2","3","4","5"]},"17":{"question":"Четырехзначное число начинается с цифры 5. Эту цифру переставили в конец числа. Полученное число оказалось на 747 меньше исходного. Какова сумма цифр этого числа?","choices":["12","14","16","18","20"]},"18":{"question":"В ряд стоят три коробки, в каждой по 11 конфет. Я беру по одной конфете из каждой коробки в таком порядке: левая, центральная, правая, центральная, левая, центральная, и так далее до тех пор, пока в центральной коробке не закончатся конфеты. В одной из двух крайних коробок осталось больше конфет. Сколько?","choices":["1","2","5","6","11"]},"19":{"question":"На игральном кубике общее число точек на любых двух противоположных гранях равно 7. Дженни склеила столбик из 6 таких кубиков и подсчитала общее число точек на всех наружных гранях. Какое самое большое число она могла получить?","choices":["106","96","95","91","84"]},"20":{"question":"Сколько существует трехзначных чисел, у которых сумма цифр равна 4?","choices":["10","9","8","7","6"]},"21":{"question":"Какое самое маленькое число спичек можно добавить к этой фигуре, чтобы получить точно 11 квадратов?","choices":["2","3","4","5","6"],"image":"assets/legacy-conditions/2001/manual-21.webp","imageWidth":192,"imageHeight":188},"22":{"question":"Есть 6 карточек с цифрами 1, 2, 3, 4, 5 и 6. Используя их, можно составить два трехзначных числа, например, 645 и 321. Вася составил эти числа так, что их разность оказалась самой маленькой из всех возможных. Эта разность равна","choices":["89","69","56","47","38"]},"23":{"question":"Кубик лежит на листе бумаги в клетку, как показано на рисунке. Кубик перекатывают через ребра в направлениях, указанных стрелочками. Сколько точек окажется сверху, когда кубик попадет на клетку, отмеченную звездочкой?","choices":["1","2","3","4","другой ответ"],"image":"assets/legacy-conditions/2001/task-23.webp","imageWidth":379,"imageHeight":190},"24":{"question":"Какие два из нарисованных восьмиугольников раскрашены одинаково?","choices":["3 и 6","2 и 6","1 и 3","4 и 6","5 и 2"],"image":"assets/legacy-conditions/2001/task-24.webp","imageWidth":905,"imageHeight":191},"25":{"question":"Про число a известно, что его последняя цифра равна 1, и что оно делится ровно на десять различных чисел (включая 1 и a). На сколько различных чисел делится число 10a?","choices":["20","30","40","50","100"]},"26":{"question":"Три черепахи – Анди, Банди и Канди – соревнуются в беге на дистанцию 30 м. Они стартовали одновременно. Когда Анди финишировала, Банди оставалось до финиша 10 м, а Канди была на 4 м впереди Банди. На каком расстоянии до финиша будет Банди, когда Канди закончит дистанцию, если каждая черепаха движется с постоянной скоростью?","choices":["2 м","3 м","4 м","5 м","6 м"]}}};
'use strict';

(() => {
  const latin = ['A', 'B', 'C', 'D', 'E'];
  const cyrillic = ['А', 'Б', 'В', 'Г', 'Д'];
  const escape = value => String(value).replaceAll('&', '&amp;').replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;').replaceAll('"', '&quot;');
  const archive = globalThis.KENGURU_ARCHIVE ??= {};
  const source = 'assets/kenguru';
  const ink = '#173439';
  const teal = '#237e79';
  const mint = '#e5f2ea';
  const muted = '#e8eee8';
  const line = '#b3c6bf';
  const gold = '#f7dda8';

  const text = (x, y, value, size = 27, color = ink, anchor = 'middle') =>
    `<text x="${x}" y="${y}" fill="${color}" font-family="system-ui, sans-serif" font-weight="700" font-size="${size}" text-anchor="${anchor}" dominant-baseline="middle">${escape(value)}</text>`;
  const box = (x, y, w, h, fill, stroke = 'none', radius = 10) =>
    `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${radius}" fill="${fill}" stroke="${stroke}"/>`;
  const segment = (x1, y1, x2, y2, color, width = 3) =>
    `<path d="M${x1} ${y1} L${x2} ${y2}" fill="none" stroke="${color}" stroke-width="${width}" stroke-linecap="round"/>`;
  const dot = (x, y, radius, fill) => `<circle cx="${x}" cy="${y}" r="${radius}" fill="${fill}"/>`;
  const svg = (width, height, label, inside, className = 'legacy-scene') =>
    `<svg class="${className}" viewBox="0 0 ${width} ${height}" role="img" aria-label="${escape(label)}">${inside}</svg>`;
  const image = (url, width, height) => `<image href="${url}" width="${width}" height="${height}"/>`;
  const progress = (frame, end) => Math.max(0, Math.min(1, frame / end));

  function renderOriginal(url, width, height, label, mark, frame) {
    let focus = '';
    if (mark) {
      const [x, y, w, h] = mark;
      const dash = .68 + .32 * progress(frame, 8);
      focus = `<rect x="${x - 4}" y="${y - 2}" width="${w + 8}" height="${h + 4}" rx="4" fill="none" stroke="${teal}" stroke-width="4" pathLength="1" stroke-dasharray="${dash} 1"/>`;
    }
    return svg(width, height, label, image(url, width, height) + focus);
  }

  function crop(url, width, height, [sx, sy, sw, sh], x, y, w, h) {
    return `<svg x="${x}" y="${y}" width="${w}" height="${h}" viewBox="${sx} ${sy} ${sw} ${sh}" style="overflow:hidden">${image(url, width, height)}</svg>`;
  }

  function workedScene([height, drawing], label, answer) {
    const size = 720;
    const band = answer ? 51 : 0;
    const badge = answer
      ? box(16, height, size - 32, 42, mint, line) + text(size / 2, height + 21, `Ответ ${answer}`, 24, teal)
      : '';
    return svg(size, height + band, label, drawing + badge, 'legacy-scene legacy-worked-scene');
  }

  // Extract only equations that the author explicitly uses in this step. A
  // space can group thousands, so it must not split their numeric tokens.
  const number = String.raw`[−-]?\d+(?:[ \u00a0\u202f]\d{3}(?!\d))*(?:[.,]\d+)?`;
  const operator = String.raw`[+−–×·⋅*÷:/=<>≤≥-]`;
  const equation = new RegExp(String.raw`${number}(?:\s*${operator}\s*${number})+`, 'gu');
  const tokens = new RegExp(String.raw`^(${number})|(${operator})\s*(${number})`, 'gu');

  function equationsIn(message) {
    return [...message.matchAll(equation)].map(match => match[0])
      .filter(value => /[=<>≤≥]/u.test(value))
      .map(value => [...value.matchAll(tokens)].flatMap(([, first, sign, next]) => first ? [first] : [sign, next]));
  }

  function drawEquations(rows, frame) {
    const drawing = rows.map((parts, row) => {
      const current = Math.min(parts.length - 1, Math.floor(Math.max(0, frame - row * 4) / 2));
      const sizes = parts.map((part, i) => i % 2 ? 32 : Math.max(48, 23 + part.length * 17));
      const width = sizes.reduce((sum, w) => sum + w, 0);
      const factor = Math.min(640 / width, 1);
      let x = (720 - width * factor) / 2;
      const y = 15 + row * 75;
      return box(16, y, 688, 62, '#f6f8f3') + parts.map((part, i) => {
        const w = sizes[i] * factor;
        const highlight = current === i;
        const result = i === parts.length - 1;
        const plate = (i % 2 === 0 || highlight)
          ? box(x + 2, y + 7, w - 4, 48, highlight ? gold : result ? mint : '#fff', result ? teal : 'none') : '';
        const item = plate + text(x + w / 2, y + 31, part, 32 * factor, result ? teal : ink);
        x += w;
        return item;
      }).join('');
    }).join('');
    return [rows.length * 75 + 13, drawing];
  }

  // The checked statement and the worksheet choices are transcribed together.
  // For illustrated choices, the approach below uses the original artwork.
  const authored = {
    '2001/3': {
      question: 'У Йозефа было 7 палочек. Он разломал одну из них пополам. Сколько теперь у него палочек?',
      choices: ['5', '6', '7', '8', '9'],
      draw: drawSticks,
    },
    '2002/2': {
      question: 'Чему равно число 2 + 2 − 2 + 2 − 2 + 2 − 2 + 2 − 2 + 2?',
      choices: ['0', '2', '4', '12', '20'],
      draw: drawPairs,
    },
    '2003/3': {
      question: 'На какой картинке сердечки составляют ровно три четверти от общего числа фигурок?',
      crop: [73, 65, 662, 131],
      illustration: 'Пять рисунков с сердечками, ромбами и треугольниками, варианты от A до E',
      draw: drawHearts,
    },
    '2004/4': {
      question: 'Сережа шел по лестнице, шагая через ступеньку (первую ступеньку он пропустил). При этом он считал шаги: «Один, два, три…». После того, как он сказал «пять», оказалось, что осталась одна ступенька. Сколько всего ступенек на лестнице?',
      choices: ['5', '7', '9', '11', '12'],
      draw: drawStairs,
    },
    '2005/3': {
      question: 'Каждый из восьми кенгуру может перепрыгнуть на любую клетку квадратной таблицы 4 × 4. Им надо расположиться так, чтобы в каждой строчке и каждом столбце этой таблицы оказалось ровно по 2 кенгуру. Какое наименьшее число кенгуру должно для этого прыгнуть?',
      choices: ['4', '3', '2', '1', '0'],
      crop: [537, 8, 244, 240],
      illustration: 'Квадратная таблица с восемью кенгуру',
      draw: drawKangaroos,
    },
    '2006/10': {
      question: 'Петя прибавляет различные однозначные числа к числу 96. Сколько раз он получит трехзначное число?',
      choices: ['3', '4', '5', '6', '7'],
      draw: drawNumberLine,
    },
    '2007/1': {
      question: 'Сколько общих букв у слов КЕНГУРУ и МАТЕМАТИКА?',
      choices: ['1', '2', '3', '4', '5'],
      draw: drawLetters,
    },
    '2008/6': {
      question: 'В первом аквариуме на 12 рыбок больше, чем во втором. Сколько рыбок надо переселить из первого аквариума во второй, чтобы рыбок в них стало поровну?',
      choices: ['12', '8', '6', '4', '2'],
      draw: drawAquariums,
    },
    '2009/2': {
      question: '200 × 9 + 200 + 9 = ?',
      choices: ['418', '1909', '2009', '4018', '20009'],
    },
    '2010/2': {
      question: 'Дети измерили шагами длину дорожки. У Ани получилось 17 шагов, у Наташи 15, у Дениса 14, у Вани 13 и у Тани 12. Кто из этих детей имеет самый длинный шаг?',
      choices: ['Аня', 'Наташа', 'Денис', 'Ваня', 'Таня'],
      draw: (step, frame) => drawBars(
        ['Аня', 'Наташа', 'Денис', 'Ваня', 'Таня'], [17, 15, 14, 13, 12], step === 2 ? 4 : -1, frame),
    },
    '2011/3': {
      question: 'Через три с половиной часа отправляется поезд, на котором Сёма поедет к бабушке. Боясь проспать, он проснулся полтора часа назад. За сколько часов до отправления поезда Сёма проснулся?',
      choices: ['за полтора часа', 'за 2 часа', 'за 3 с половиной часа', 'за 4 часа', 'за 5 часов'],
      draw: (step, frame) => drawTimeline(
        ['Пробуждение', 'Сейчас', 'Отправление'], [1.5, 3.5], ['1,5 ч', '3,5 ч'], step === 2 ? '5 часов' : '', frame),
    },
    '2012/4': {
      question: 'Три воздушных шарика стоят на 12 рублей больше, чем один шарик. Сколько стоит один шарик?',
      choices: ['4 руб.', '6 руб.', '8 руб.', '10 руб.', '12 руб.'],
      draw: drawBalloons,
    },
    '2013/4': {
      question: 'Миша измерил длины пяти палочек и записал результаты этих измерений. Какой из результатов А–Д самый большой?',
      choices: ['3 дм 2 см', '3 см 7 мм', '35 мм', '3 см', '302 мм'],
      draw: (step, frame) => step === 1
        ? drawEquations(equationsIn('300 + 20 = 320'), frame)
        : drawBars(['А', 'Б', 'В', 'Г', 'Д'], [320, 37, 35, 30, 302], 0, frame, ' мм'),
    },
    '2014/1': {
      question: 'Боря выложил из одинаковых палочек слово КЕНГУРУ. Сколько букв сложены из 5 палочек?',
      choices: ['2', '3', '4', '5', '6'],
      crop: [447, 4, 348, 81],
      illustration: 'Буквы слова КЕНГУРУ, сложенные из палочек',
      draw: drawStickLetters,
    },
    '2015/2': {
      question: 'Чему равна сумма двадцати сотен и пятнадцати?',
      choices: ['35', '215', '2015', '20015', '200015'],
    },
    '2016/2': {
      question: 'Крошке Ру 17 марта исполняется 7 недель и 3 дня. Когда ему исполнится 9 недель?',
      choices: ['21 марта', '24 марта', '26 марта', '28 марта', '30 марта'],
      draw: (step, frame) => drawTimeline(
        ['17 марта', step === 2 ? '21 марта' : '8 недель', step === 2 ? '28 марта' : '9 недель'],
        [4, 7], ['4 дня', '7 дней'], step === 2 ? '11 дней' : '', frame),
    },
    '2017/1': {
      question: 'Кенга составила пять примеров на сложение. Какая сумма самая большая?',
      choices: ['2 + 0 + 1 + 7', '2 + 0 + 17', '20 + 17', '20 + 1 + 7', '201 + 7'],
      draw: drawSums,
    },
    '2018/3': {
      question: 'В Петербурге 15 марта в 16 часов пошел снег, а 16 марта в 15 часов снегопад закончился. Сколько часов он продолжался?',
      choices: ['11', '12', '23', '24', '25'],
      draw: (step, frame) => drawTimeline(
        step === 1 ? ['15 марта, 16:00', 'Полночь'] : ['15 марта, 16:00', 'Полночь', '16 марта, 15:00'],
        step === 1 ? [8] : [8, 15], step === 1 ? ['8 ч'] : ['8 ч', '15 ч'], step === 2 ? '23 часа' : '', frame, 23),
    },
    '2019/1': {
      question: 'В зоопарке 21 ноября 2018 года родился кенгуренок. Сколько месяцев ему исполнилось 21 марта 2019 года?',
      choices: ['3', '4', '5', '6', '7'],
      draw: (step, frame) => drawTimeline(
        step === 1 ? ['21 нояб.', '21 дек.', '21 янв.'] : ['21 нояб.', '21 дек.', '21 янв.', '21 февр.', '21 марта'],
        step === 1 ? [1, 1] : [1, 1, 1, 1], step === 1 ? ['1 мес.', '1 мес.'] : ['1 мес.', '1 мес.', '1 мес.', '1 мес.'],
        step === 2 ? '4 месяца' : '', frame, 4),
    },
  };

  function drawSticks(step, frame) {
    let drawing = '';
    for (let i = 0; i < 6; i++) drawing += segment(101 + i * 70, 38, 101 + i * 70, 117, teal, 11);
    drawing += text(275, 150, '6 целых', 26);
    const gap = step === 1 ? 0 : 20 + 9 * progress(frame, 8);
    drawing += segment(567 - gap, 38, 567 - gap, 74, '#bc6340', 11);
    drawing += segment(567 + gap, 82, 567 + gap, 117, '#bc6340', 11);
    drawing += text(567, 150, step === 1 ? 'сломанная' : '2 половины', 26);
    return [180, drawing];
  }

  function drawPairs(step, frame) {
    let drawing = box(17, 22, 119, 61, mint) + text(77, 52, '2 + 2', 30);
    const active = Math.min(3, Math.floor(Math.max(0, frame) / 4));
    for (let i = 0; i < 4; i++) {
      const x = 151 + 139 * i;
      drawing += box(x, 22, 130, 61, step === 1 && i === active ? gold : muted);
      drawing += text(x + 65, 52, step === 1 ? '−2 + 2' : '0', 30);
      if (step === 1) drawing += segment(x + 65, 89, x + 65, 111, teal) + text(x + 65, 137, '0', 26, teal);
    }
    if (step === 2) drawing += text(360, 137, '2 + 2 = 4', 33, teal);
    return [173, drawing];
  }

  function drawHearts(step, frame, card) {
    if (step === 1) {
      let drawing = '';
      for (let i = 0; i < 4; i++) {
        const x = 105 + i * 128;
        drawing += box(x, 40, 105, 81, i === 3 ? muted : mint, line);
        drawing += text(x + 52, 80, i === 3 ? '◇' : '♥', 49, i === 3 ? ink : '#a34849');
      }
      return [175, drawing + text(360, 145, '3 из 4', 30, teal)];
    }
    const [url, w, h] = card;
    const choiceImage = globalThis.KENGURU_CHOICE_LAYOUTS?.['2003-3-4/3']?.options[3]?.image;
    const drawing = choiceImage
      ? `<image href="${escape(choiceImage)}" x="251" y="11" width="228" height="240"/>`
      : crop(url, w, h, [493, 66, 76, 80], 251, 11, 228, 240);
    const alpha = .45 + progress(frame, 9) * .55;
    return [260, drawing +
      `<g opacity="${alpha}">` +
      box(256, 15, 216, 158, 'none', '#a34849') + box(256, 176, 216, 73, 'none', teal) +
      text(490, 94, '9 сердец', 27, '#a34849', 'start') +
      text(490, 206, '3 другие фигуры', 23, teal, 'start') + '</g>'];
  }

  function drawStairs(step, frame) {
    let drawing = '';
    for (let i = 1; i <= 11; i++) {
      const x = 26 + 60 * (i - 1);
      const y = 176 - 13 * (i - 1);
      const landed = i % 2 === 0;
      const active = landed && i / 2 === Math.min(5, 1 + Math.floor(Math.max(frame, 0) / 4));
      const remaining = i === 11 && step === 2;
      drawing += box(x, y, 59, 36, active ? gold : remaining || landed ? mint : muted, line, 4);
      if (i < 11 || remaining) drawing += text(x + 30, y + 18, i, 24, landed || remaining ? teal : ink);
      if (landed) drawing += dot(x + 30, y - 15, active ? 8 : 5, teal);
      if (remaining) drawing += text(x + 30, y - 20, '+1', 22, teal);
    }
    return [225, drawing];
  }

  function drawKangaroos(step, frame, card) {
    const [url, w, h] = card;
    const locations = [[0, 0], [0, 1], [1, 0], [1, 3], [2, 2], [2, 3], [3, 2], [1, 2]];
    let drawing = '';
    for (let row = 0; row < 4; row++) {
      for (let col = 0; col < 4; col++) {
        const fill = step === 1 && (row === 1 || col === 2) ? gold
          : row === 3 && col === 1 ? mint : '#fff';
        drawing += box(204 + col * 64, 14 + row * 64, 64, 64, fill, line, 0);
      }
    }
    const moving = step === 2 ? (frame === 0 ? 1 : progress(frame, 10)) : 0;
    if (step === 2 && frame > 0) {
      drawing += `<path d="M364 110 Q230 144 300 238" fill="none" stroke="${teal}" stroke-width="3" stroke-dasharray="7 5"/>`;
    }
    locations.forEach(([row, col], i) => {
      const active = i === locations.length - 1;
      const shift = active ? moving : 0;
      const x = 210 + col * 64 - shift * 64;
      const y = 21 + row * 64 + shift * 128 - 37 * Math.sin(shift * Math.PI);
      if (active) drawing += box(x - 3, y - 3, 58, 57, mint, teal, 7);
      drawing += `<svg x="${x}" y="${y}" width="52" height="50" viewBox="549 19 49 46" style="overflow:hidden;mix-blend-mode:multiply">${image(url, w, h)}</svg>`;
    });
    const counts = moving === 1 ? [2, 2, 2, 2] : moving === 0 ? [2, 3, 2, 1] : [2, 2, 2, 1];
    for (let i = 0; i < 4; i++) {
      drawing += text(489, 46 + i * 64, counts[i], 24, teal);
      drawing += text(236 + i * 64, 296, i === 1 ? counts[3] : i === 2 ? counts[1] : 2, 24, teal);
    }
    return [321, drawing];
  }

  function drawNumberLine(step, frame) {
    let drawing = segment(44, 99, 676, 99, line, 4);
    for (let i = 0; i < 10; i++) {
      const x = 45 + i * 70;
      const marked = i === 4 || (step === 2 && i > 4);
      const active = i === 4 + Math.min(step === 1 ? 0 : 5, Math.floor(Math.max(0, frame) / 3));
      if (marked) drawing += box(x - 28, 53, 56, 44, active ? gold : mint);
      drawing += text(x, 75, 96 + i, 23, marked ? teal : ink) + dot(x, 99, marked ? 6 : 4, marked ? teal : line);
      if (marked) drawing += text(x, 126, '+' + i, 20, teal);
    }
    return [155, drawing];
  }

  function drawLetters(step, frame) {
    const words = ['КЕНГУРУ', 'МАТЕМАТИКА'];
    const active = Math.min(words[0].length - 1, Math.floor(Math.max(0, frame) / 3));
    return [166, words.map((word, row) => [...word].map((letter, i) => {
      const x = 360 - word.length * 32 + i * 64;
      const y = 19 + row * 67;
      const common = step === 2 && 'КЕ'.includes(letter);
      const comparable = step === 1 && (row === 0 ? i === active : letter === words[0][active]);
      return box(x, y, 56, 54, common ? mint : comparable ? gold : muted, common ? teal : line) +
        text(x + 28, y + 27, letter, 30, common ? teal : ink);
    }).join('')).join('')];
  }

  function drawAquariums(step, frame) {
    const moved = step === 1 ? 1 : 6;
    const now = frame === 0 ? moved : Math.min(moved, 1 + Math.floor(frame / 3));
    let drawing = '';
    for (let tank = 0; tank < 2; tank++) {
      const x = 21 + tank * 365;
      drawing += box(x, 18, 313, 128, mint, line);
      drawing += text(x + 156, 40, tank ? 'Второй аквариум' : 'Первый аквариум', 22);
      drawing += text(x + 40, 96, '□ +', 25, teal);
      for (let i = 0; i < (tank ? now : 12 - now); i++) {
        drawing += dot(x + 81 + (i % 6) * 36, 81 + Math.floor(i / 6) * 33, 11, tank ? '#bc6340' : teal);
      }
    }
    drawing += text(360, 82, '→', 27, ink);
    const difference = now === 6 ? '6 = 6' : `${12 - now} − ${now} = ${12 - 2 * now}`;
    drawing += text(360, 174, difference, 29, teal);
    return [197, drawing];
  }

  function drawBars(names, values, highlighted, frame, unit = '') {
    const max = Math.max(...values);
    const active = Math.min(values.length - 1, Math.floor(Math.max(0, frame) / 3));
    let drawing = '';
    for (let i = 0; i < values.length; i++) {
      const y = 12 + i * 46;
      const w = values[i] / max * 450;
      drawing += text(124, y + 17, names[i], 22, ink, 'end');
      drawing += box(146, y, w, 34, i === highlighted ? teal : i === active ? gold : muted, line, 7);
      drawing += text(156 + w, y + 17, values[i] + unit, 22, i === highlighted ? teal : ink, 'start');
    }
    return [values.length * 46 + 6, drawing];
  }

  function drawTimeline(labels, sizes, durations, total, frame, span = sizes.reduce((sum, size) => sum + size, 0)) {
    const active = Math.min(sizes.length - 1, Math.floor(Math.max(0, frame) / 6));
    let x = 103;
    let drawing = '';
    sizes.forEach((size, i) => {
      const end = x + 514 * size / span;
      drawing += segment(x, 65, end, 65, i === active ? '#c07848' : teal, 8);
      drawing += dot(x, 65, 8, teal);
      drawing += text(x, 100, labels[i], 21);
      drawing += text((x + end) / 2, 34, durations[i], 25, teal);
      x = end;
    });
    drawing += dot(x, 65, 8, teal) + text(x, 100, labels.at(-1), 21);
    if (total) drawing += box(103, 129, 514, 40, mint) + text(360, 149, total, 26, teal);
    return [total ? 183 : 128, drawing];
  }

  function drawBalloons(step, frame) {
    const active = Math.min(2, 1 + Math.floor(Math.max(0, frame) / 4));
    let drawing = segment(343, 62, 586, 62, teal, 3) + text(464, 36, '12 руб.', 26, teal);
    for (let i = 0; i < 3; i++) {
      const x = 175 + i * 144;
      const color = i === 0 ? '#a9b9b2' : i === active ? '#bc6340' : teal;
      drawing += dot(x, 118, 38, color);
      drawing += box(x - 6, 151, 12, 12, color, 'none', 0);
      drawing += segment(x, 162, x, 181, color);
      drawing += text(x, 207, i === 0 ? 'вычитаем' : step === 1 ? '?' : '6 руб.', 25, color);
      if (i === 0) drawing += segment(x - 45, 165, x + 45, 77, '#7d4940', 4);
    }
    return [239, drawing];
  }

  function drawStickLetters(step, frame, card) {
    const [url, w, h] = card;
    const sources = [[449, 42], [492, 48], [541, 53], [597, 49], [645, 46], [692, 52], [745, 48]];
    const values = [4, 5, 5, 3, 3, 5, 3];
    const active = Math.min(6, Math.floor(Math.max(0, frame) / 3));
    let drawing = '';
    for (let i = 0; i < sources.length; i++) {
      const [sx, sw] = sources[i];
      const x = 24 + i * 98;
      const relevant = step === 2 ? values[i] === 5 : values[i] !== 5;
      drawing += box(x, 21, 85, 126, relevant ? mint : muted, relevant ? teal : line);
      drawing += crop(url, w, h, [sx, 8, sw, 75], x + 14, 30, 56, 77);
      if (relevant) drawing += text(x + 43, 125, values[i], 24, active === i ? '#a24d36' : teal);
    }
    return [167, drawing];
  }

  function drawSums(step, frame) {
    if (step === 2) return drawBars(['А', 'Б', 'В', 'Г', 'Д'], [10, 19, 37, 28, 208], 4, frame);
    const expressions = authored['2017/1'].choices;
    const drawing = expressions.map((value, i) => {
      const x = 12 + i * 140;
      return box(x, 25, 135, 61, i === 4 ? mint : muted, i === 4 ? teal : line) +
        text(x + 67, 55, value, 22, i === 4 ? teal : ink);
    }).join('');
    return [113, drawing];
  }

  for (const [year, label, tasks] of globalThis.KENGURU_LEGACY ?? []) {
    const letters = year < 2008 ? latin : cyrillic;
    const lessons = [];
    const scenes = [];
    for (const [i, [width, height, , marks, key, name, explanation, note]] of tasks.entries()) {
      const number = i + 1;
      const answer = key === '?' ? null : latin.indexOf(key);
      const originalImage = `assets/years/${year}/task-${String(number).padStart(2, '0')}.webp`;
      const card = [originalImage, width, height];
      const authoredTask = authored[year + '/' + number];
      const imported = globalThis.KENGURU_LEGACY_CONDITIONS?.[year]?.[number];
      const native = authoredTask ?? imported;
      const illustration = !authoredTask && imported?.image
        ? svg(imported.imageWidth, imported.imageHeight, 'Рисунки и варианты из условия',
            `<image href="${escape(imported.image)}" width="${imported.imageWidth}" height="${imported.imageHeight}"/>`)
          .replace('<svg ', `<svg style="max-width:${imported.imageWidth}px" `)
        : '';
      const steps = [
        ['Твоё решение', 'Условие задачи', 'Выбери свой вариант ответа.'],
        ...explanation.map(([heading, message], stage) => [
          stage === explanation.length - 1 ? 'Ответ' : 'Шаг ' + (stage + 1), heading, message,
        ]),
      ];
      const formulas = explanation.map(([, message]) => equationsIn(message));
      const choice = answer === null ? '' : letters[answer];
      const description = `Условие и варианты задачи ${number} из оригинала.`;
      lessons.push({
        number,
        title: name,
        short: name,
        skill: '',
        answer,
        choices: native?.choices ?? ['', '', '', '', ''],
        choiceImages: native?.choiceImages,
        question: native?.question ?? '',
        conditionImage: !authoredTask ? imported?.image : undefined,
        questionNote: note,
        legacyOriginal: true,
        hideIntroText: Boolean(native),
        showCompletedStep: true,
        points: i < 10 ? 3 : i < 20 ? 4 : 5,
        originalImage,
        steps,
      });
      scenes.push((step, frame) => {
        if (step === 0 && authoredTask) {
          if (!authoredTask.crop) return '';
          const region = authoredTask.crop;
          const cropHeight = Math.round(720 * region[3] / Math.max(600, region[2]));
          const cropWidth = cropHeight * region[2] / region[3];
          return svg(720, cropHeight, authoredTask.illustration,
            crop(...card, region, (720 - cropWidth) / 2, 0, cropWidth, cropHeight));
        }
        if (step === 0 && native) return illustration;
        const final = step === steps.length - 1;
        const revealed = final ? choice : '';
        const answerLabel = revealed ? ` Ответ ${revealed}.` : '';
        if (step > 0) {
          const content = authoredTask?.draw
            ? authoredTask.draw(step, frame * 3, card)
            : formulas[step - 1].length ? drawEquations(formulas[step - 1], frame * 5) : null;
          if (content) return workedScene(content, steps[step][1] + '. ' + steps[step][2] + answerLabel, revealed);
          if (native) {
            if (!revealed) return '';
            return workedScene([0, ''], description + answerLabel, revealed);
          }
        }
        return renderOriginal(...card, description + answerLabel, final ? marks[answer] : null, frame);
      });
    }

    archive[year] = {
      year,
      id: year + '-3-4',
      grades: [3, 4],
      label,
      answerLetters: letters,
      sources: {
        tasksUrl: `${source}/kenguru_${year}_class_3-4.pdf`,
        answersUrl: `${source}/kenguru_${year}_answers.pdf`,
        solutionUrl: null,
      },
      lessons,
      scenes,
    };
  }
})();

